**2. JavaScript (Sorting Logic)**

```javascript
const table = document.querySelector('.table');
let sortColumn = 0; // Default sort column (0-based index)
let sortOrder = 1; // 1 for ascending, -1 for descending

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    const columnIndex = Array.from(event.target.parentNode.children).indexOf(event.target);
    const sortType = event.target.dataset.sort;

    // Toggle sort order if clicking the same column
    if (columnIndex === sortColumn) {
      sortOrder *= -1;
    } else {
      sortColumn = columnIndex;
      sortOrder = 1; // Reset to ascending for the new column
    }

    sortTable(sortColumn, sortOrder, sortType);
  }
});

function sortTable(columnIndex, sortOrder, sortType) {
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  rows.sort((a, b) => {
    const cellA = a.querySelectorAll('td')[columnIndex].textContent;
    const cellB = b.querySelectorAll('td')[columnIndex].textContent;

    let valueA, valueB;

    switch (sortType) {
      case 'number':
        valueA = parseFloat(cellA);
        valueB = parseFloat(cellB);
        break;
      case 'date':
        valueA = new Date(cellA);
        valueB = new Date(cellB);
        break;
      default: // string
        valueA = cellA.toLowerCase(); // Case-insensitive sorting
        valueB = cellB.toLowerCase();
    }

    if (valueA < valueB) {
      return sortOrder * -1;
    }
    if (valueA > valueB) {
      return sortOrder;
    }
    return 0;
  });

  // Re-append the sorted rows to the table body
  const tbody = table.querySelector('tbody');
  rows.forEach(row => tbody.appendChild(row));
}
```

